85						// shared runtime via leader-only `dependOn` — the others
86						// either preload without executing (`modulepreload`) or
87						// produce CSS chunks (`stylesheet`) which have no runtime
88						// to share. CSS entries must NOT chain into a JS leader
89						// either, because the resulting chunk would mix a CSS
90						// stylesheet with a JS runtime.
91						const isChainGroup =
92							groupKind !== "modulepreload" && groupKind !== "stylesheet";
93						/** @type {string | undefined} */
94						let leaderName;
95						for (const entry of group) {
96							const dependOn =
97								isChainGroup && leaderName !== undefined
98									? [leaderName]
99									: undefined;
100							if (isChainGroup && leaderName === undefined) {
101								leaderName = entry.entryName;
102							}
103							if (groupKind === "stylesheet") {
104								stylesheetEntries.add(entry.entryName);
105							}
