112										}),
113										{
114											name: entry.entryName,
115											// Each script src / modulepreload entry gets its own
116											// filename derived from the synthetic entry name so it
117											// doesn't collide with the user's `output.filename`.
118											// For CSS entries the JS `filename` is irrelevant (no
119											// `.js` is emitted) — the CSS file's name is set on the
120											// chunk via `cssFilenameTemplate` in `afterChunks` below.
121											filename:
122												compilation.outputOptions.chunkFilename || "[name].js",
